def _build_type(type_, value, property_path=None):
    """ Builds the schema definition based on the given type for the given value.

    :param type_: The type of the value
    :param value: The value to build the schema definition for
    :param List[str] property_path: The property path of the current type,
        defaults to None, optional
    :return: The built schema definition
    :rtype: Dict[str, Any]
    """
    if type_ == 'array':
        return _build_array(value, property_path)
    elif type_ == 'object':
        return _build_object(value, property_path)
    elif type_ == 'string':
        return _build_string(value, property_path)
    elif type_ == 'number':
        return _build_number(value, property_path)
    elif type_ == 'integer':
        return _build_integer(value, property_path)
    elif type_ == 'boolean':
        return _build_boolean(value, property_path)
    elif type_ == 'null':
        return _build_null(value, property_path)
    else:
        raise ValueError('Unknown type: {}'.format(type_))

