def _build_array(value, property_path=None):
    """ Builds the schema definition for an array.

    :param List value: The array to build the schema definition for
    :param List[str] property_path: The property path of the current type,
        defaults to None, optional
    :return: The built schema definition
    :rtype: Dict[str, Any]
    """
    if not isinstance(value, list):
        raise ValueError('Expected a list, got {}'.format(type(value)))

    if not value:
        raise ValueError('Expected a non-empty list')

    if not isinstance(value[0], dict):
        raise ValueError('Expected a list of dictionaries, got {}'.format(
            type(value[0])))

